export const MAX_RESEARCH_HTML_BYTES = 200_000
export const RESEARCH_HTML_LIMIT_ERROR = 'HTML 页面超过 200 KB 上限，请精简内容后重试。'

export function parseResearchHtmlArtifact(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value) || value.version !== 1 || value.type !== 'html' ||
      Object.keys(value).length !== 4 || !['version', 'type', 'title', 'html'].every((key) => Object.hasOwn(value, key)) ||
      typeof value.title !== 'string' || !value.title.trim() || value.title.length > 256 ||
      typeof value.html !== 'string' || !value.html.trim() || new TextEncoder().encode(value.html).byteLength > MAX_RESEARCH_HTML_BYTES ||
      /<(?:iframe|frame|object|embed)\b/i.test(value.html)) return null
  return Object.freeze({ version: 1, type: 'html', title: value.title, html: value.html })
}

// Static evidence only. Never create a DOM or execute artifact code in the host.
export function researchHtmlText(html) {
  if (typeof html !== 'string') return ''
  return html.replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(script|style|template|head)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, ' ')
    .replace(/<(script|style|template|head)\b[^>]*>[\s\S]*$/gi, ' ')
    .replace(/<[^>]*>/g, '\n')
    .replace(/&(?:#(x[\da-f]+|\d+)|(amp|lt|gt|quot|apos|nbsp));/gi, (match, numeric, named) => {
      if (!numeric) return ({ amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' })[named.toLowerCase()]
      const point = numeric[0].toLowerCase() === 'x' ? parseInt(numeric.slice(1), 16) : Number(numeric)
      return point > 0 && point <= 0x10ffff && !(point >= 0xd800 && point <= 0xdfff) ? String.fromCodePoint(point) : match
    })
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '')
    .replace(/[^\S\n]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim().slice(0, 120_000)
}

// Older trusted dashboard outputs duplicated full metric explanations on the
// face of each card. Keep one visible copy of a short note; longer notes keep
// their expandable detail. The signature avoids rewriting arbitrary model HTML.
export function compactHostDashboardHtml(html) {
  if (typeof html !== 'string') return html
  html = refineComponentReadingFooter(refineStoredTemplateHtml(refineStoredSpecialChartHtml(refineCandlestickHtml(html))))
  // Previously saved host-rendered market cards keep their original HTML.
  // Apply the same surface and disclosure geometry while loading their preview.
  if (html.includes('data-sherlock-market=') && html.includes('data-sherlock-design=') && !html.includes('ODYSSEY_MARKET_PRESENTATION_V3'))
    html = html.replace('</head>', `<style>${MARKET_PRESENTATION_CSS}</style></head>`)
  // Saved host-rendered cards retain their HTML. Apply the same density fixes
  // on load so users do not need to regenerate a board to see the correction.
  if (html.includes('<body data-sherlock-market="breadth"') && html.includes('data-sherlock-design="21m-20260923-v1"') && !html.includes('data-sherlock-breadth-refined')) {
    const css = `<style data-sherlock-breadth-refined>html,body[data-sherlock-market="breadth"]{height:100%}body[data-sherlock-market="breadth"]{padding:8px 12px}.market-breadth{height:100%;display:grid;grid-template-columns:minmax(220px,1fr) minmax(260px,1fr);gap:18px;align-items:stretch}.market-distribution{min-width:0;display:flex;flex-direction:column;justify-content:center}.market-counts{font-size:10px;line-height:16px;gap:8px}.market-bar{height:10px;margin:9px 0}.market-distribution>.market-detail{line-height:15px}.market-breadth .market-metrics{min-width:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;align-content:center}.market-breadth .market-metric{min-height:64px;padding:7px 8px;background:var(--sherlock-surface-muted)}.market-breadth .market-value{font-size:16px;line-height:20px;margin-top:1px}.market-breadth .market-detail{font-size:8px;line-height:11px;margin-top:0}@media(max-width:620px){.market-breadth{grid-template-columns:1fr;gap:8px;height:auto}.market-breadth .market-metric{min-height:54px}}</style>`
    return html.replace('</head>', `${css}</head>`)
  }
  if ((html.includes('<body data-research-kind="news"') || html.includes('<body data-research-kind="reports"')) && html.includes("const all=Array.from(document.querySelectorAll('article'))") && !html.includes('class="feed-meta"') && !html.includes('data-sherlock-feed-refined')) {
    const css = `<style data-sherlock-feed-refined>body{padding:6px 10px 10px;background:var(--sherlock-surface)}.controls{margin:4px 0 5px;gap:6px;align-items:center}.controls input,.controls select,.controls button{height:27px;padding:3px 7px;font-size:11px;border-radius:4px}.controls input{min-width:120px}.list.research-feed{gap:0}.research-feed-item{display:grid;grid-template-columns:104px minmax(0,1fr);gap:0 10px;padding:6px 2px 7px;min-height:52px;border-bottom:.5px solid var(--sherlock-border)}.research-feed-item .meta{grid-row:1/3;min-width:0;font-size:10px;line-height:14px}.research-feed-item h2{margin:0;font-size:12px;line-height:16px;font-weight:600}.research-feed-item details{margin:1px 0 0;font-size:10px;line-height:14px;color:var(--sherlock-muted)}.research-feed-item details summary{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:1;overflow:hidden;list-style:none}.research-feed-item details[open] summary{-webkit-line-clamp:unset}.research-feed-item details p{margin:3px 0}.research-feed-item details .muted{display:none}#count{margin:0 0 3px;font-size:9px}@media(max-width:390px){.research-feed-item{grid-template-columns:1fr}.research-feed-item .meta{grid-row:auto}}</style>`
    return html.replace('</head>', `${css}</head>`)
  }
  if (!html.includes('<main class="list research-metrics">') ||
      !html.includes("const all=Array.from(document.querySelectorAll('article'))")) return html
  const count = (html.match(/<article class="research-metric"/g) ?? []).length
  let display = count >= 5
    ? html.replace('grid-template-columns:repeat(auto-fit,minmax(min(120px,100%),1fr))', 'grid-template-columns:repeat(3,minmax(0,1fr))')
    : html
  display = display.replace(/<p class="research-metric-detail">([^<]+)<\/p><details><summary>详情<\/summary><p>\1<\/p><\/details>/g,
    (match, detail) => detail.length > 40 ? `<details><summary>查看口径</summary><p>${detail}</p></details>` : `<p class="research-metric-detail">${detail}</p>`)
  return display
}

