// DIN Pro Latin subsets from the user-provided local font family; no font network requests.
const RESEARCH_COMPONENT_DIN_FACES = "@font-face{font-family:\"EWork DIN Pro\";font-style:normal;font-weight:100 399;font-display:swap;src:url(data:font/woff;base64,) format(\"woff\");unicode-range:U+0020-024F,U+1E00-1EFF,U+2000-206F,U+20A0-20CF,U+2212}@font-face{font-family:\"EWork DIN Pro\";font-style:normal;font-weight:400 599;font-display:swap;src:url(data:font/woff;base64,) format(\"woff\");unicode-range:U+0020-024F,U+1E00-1EFF,U+2000-206F,U+20A0-20CF,U+2212}@font-face{font-family:\"EWork DIN Pro\";font-style:normal;font-weight:600 900;font-display:swap;src:url(data:font/woff;base64,) format(\"woff\");unicode-range:U+0020-024F,U+1E00-1EFF,U+2000-206F,U+20A0-20CF,U+2212}"
export function researchComponentTypographyCss(scope, options = {}) {
  const noto = options.notoFont === 'runtime' ? '' : options.notoFont === 'local'
    ? '@font-face{font-family:"Noto Sans SC";font-style:normal;font-weight:100 900;font-display:swap;src:url("/fonts/NotoSansSC.woff2") format("woff2");}'
    : researchNotoFontCss
  return RESEARCH_COMPONENT_DIN_FACES + noto + `@layer sherlock-component-typography{:is(:is(${scope}),:is(${scope}) *){font-family:"EWork DIN Pro","Noto Sans SC",sans-serif!important}[data-sherlock-market] :is(table,table *){font-family:"EWork Market DIN Regular","Noto Sans SC",sans-serif!important}}`
}
